     "ex": "class RetryingSender:                         # composition: wraps any Sender\n    def __init__(self, inner, attempts=3):\n        self.inner, self.attempts = inner, attempts\n    def send(self, to, text):\n        for n in range(1, self.attempts + 1):\n            try:\n                return self.inner.send(to, text)\n            except ConnectionError as e:\n                print(f\"attempt {n} failed: {e}\")\n        raise ConnectionError(\"gave up\")\n\nclass FlakySender:\n    def __init__(self):\n        self.calls = 0\n    def send(self, to, text):\n        self.calls += 1\n        if self.calls < 3:\n            raise ConnectionError(\"timeout\")\n        print(f\"sent to {to}: {text}\")\n\nRetryingSender(FlakySender()).send(\"0100\", \"Your order shipped\")",
